---level4 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl4_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end				game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		if dialog.show("Level4-1", facePutong) ==1 then break end		if dialog.showMinTime("Level4-2", faceManyi,0) ==1 then break end		camera.setFollowRoleMode(false)		camera.gotoPosition(475,1744)		sound.play("54-1")		if dialog.showMinTime("Level4-3", faceJingya,0) ==1 then break end		if dialog.show("Level4-4", faceWunai) ==1 then break end		camera.gotoRole()		if dialog.show("Level4-5", faceRenzhen) ==1 then break end		camera.setFollowRoleMode(true)		--set story viewed flag        global.setBool("lvl4_b1")				game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false		until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end